> [38f497d](https://github.com/bitcoin/bitcoin/pull/36781/changes/38f497d04cb0dd756639549edd7d4d1ec0d1d608) _refactor: use consistent parameter names in declarations and definitions_:

I understand you chose the version with the minimal diff, but since we’re fixing inconsistencies, we might as well use `in_bytes` / `out_bytes` consistently for both `Crypt` methods.

<details>
<summary>Use consistent ChaCha20 buffer parameter names</summary>

```diff
diff --git a/src/crypto/chacha20.cpp b/src/crypto/chacha20.cpp
index 6bdffe691a..ba20293225 100644
--- a/src/crypto/chacha20.cpp
+++ b/src/crypto/chacha20.cpp
@@ -299,32 +299,32 @@ void ChaCha20::Keystream(std::span<std::byte> out) noexcept
     }
 }

-void ChaCha20::Crypt(std::span<const std::byte> input, std::span<std::byte> output) noexcept
+void ChaCha20::Crypt(std::span<const std::byte> in_bytes, std::span<std::byte> out_bytes) noexcept
 {
-    assert(input.size() == output.size());
+    assert(in_bytes.size() == out_bytes.size());

-    if (!input.size()) return;
+    if (!in_bytes.size()) return;
     if (m_bufleft) {
-        unsigned reuse = std::min<size_t>(m_bufleft, input.size());
+        unsigned reuse = std::min<size_t>(m_bufleft, in_bytes.size());
         for (unsigned i = 0; i < reuse; i++) {
-            output[i] = input[i] ^ m_buffer[m_aligned.BLOCKLEN - m_bufleft + i];
+            out_bytes[i] = in_bytes[i] ^ m_buffer[m_aligned.BLOCKLEN - m_bufleft + i];
         }
         m_bufleft -= reuse;
-        output = output.subspan(reuse);
-        input = input.subspan(reuse);
+        out_bytes = out_bytes.subspan(reuse);
+        in_bytes = in_bytes.subspan(reuse);
     }
-    if (input.size() >= m_aligned.BLOCKLEN) {
-        size_t blocks = input.size() / m_aligned.BLOCKLEN;
-        m_aligned.Crypt(input.first(blocks * m_aligned.BLOCKLEN), output.first(blocks * m_aligned.BLOCKLEN));
-        output = output.subspan(blocks * m_aligned.BLOCKLEN);
-        input = input.subspan(blocks * m_aligned.BLOCKLEN);
+    if (in_bytes.size() >= m_aligned.BLOCKLEN) {
+        size_t blocks = in_bytes.size() / m_aligned.BLOCKLEN;
+        m_aligned.Crypt(in_bytes.first(blocks * m_aligned.BLOCKLEN), out_bytes.first(blocks * m_aligned.BLOCKLEN));
+        out_bytes = out_bytes.subspan(blocks * m_aligned.BLOCKLEN);
+        in_bytes = in_bytes.subspan(blocks * m_aligned.BLOCKLEN);
     }
-    if (!input.empty()) {
+    if (!in_bytes.empty()) {
         m_aligned.Keystream(m_buffer);
-        for (unsigned i = 0; i < input.size(); i++) {
-            output[i] = input[i] ^ m_buffer[i];
+        for (unsigned i = 0; i < in_bytes.size(); i++) {
+            out_bytes[i] = in_bytes[i] ^ m_buffer[i];
         }
-        m_bufleft = m_aligned.BLOCKLEN - input.size();
+        m_bufleft = m_aligned.BLOCKLEN - in_bytes.size();
     }
 }

